public class RemoveSaleOrderDetail
{
    public record Command(Guid Id) : ICommand;

    public class CommandValidator : AbstractValidator<Command>
    {
        public CommandValidator(ILocalizationService localizationService)
        {
            RuleFor(x => x.Id)
                .NotEmpty()
                    .WithName(localizationService.GetPropertyName("SaleOrderDetail.Id"));
        }
    }

    public class CommandHandler(
        IAppDbContext context,
        ILogger<CommandHandler> logger) : ICommandHandler<Command>
    {
        public async Task HandleAsync(Command command, CancellationToken cancellationToken = default)
        {
            var entity = await context.SaleOrderDetails
                .Include(x => x.SaleOrder)
                .FirstOrDefaultAsync(x => x.Id == command.Id, cancellationToken)
                ?? throw BusinessRule.SaleOrderDetails.NotFound.ToBusinessException([command.Id]);

            if (entity.SaleOrder.Status != SoStatus.Draft)
                throw BusinessRule.SaleOrderDetails.CannotModifyNonDraftSo.ToBusinessException([entity.SaleOrder.SoNumber]);

            context.SaleOrderDetails.Remove(entity);
            await context.SaveChangesAsync(cancellationToken);

            logger.LogInformation("SaleOrderDetail {Id} removed from SO {SoNumber}", entity.Id, entity.SaleOrder.SoNumber);
        }
    }
}

