[HttpDelete("{id:guid}")]
[ProducesResponseType(StatusCodes.Status204NoContent)]
public async Task<IActionResult> Remove(Guid id, CancellationToken ct)
{
    await dispatcher.DispatchAsync(new RemoveSaleOrderDetail.Command(id), ct);
    return NoContent();
}
